class _ResponseCommand(NamedTuple):
    operation: Literal["chunk", "finish"]
    text: Optional[Text]
    kwargs: Dict[Text, Any]


class ResponseWriter:
    """Queue one streamed response for delivery outside its producer."""

    def __init__(
        self,
        channel: "OutputChannel",
        recipient_id: Text,
        start_kwargs: Dict[Text, Any],
    ) -> None:
        self._channel = channel
        self._recipient_id = recipient_id
        self._start_kwargs = start_kwargs
        self._commands: asyncio.Queue[_ResponseCommand] = asyncio.Queue()
        self._delivery_started = False
        self._end_started = False
        self._finished = False
        self._interrupted = False

    def write(self, text: Text, **kwargs: Any) -> None:
        """Queue text without waiting for channel delivery."""
        if self._interrupted:
            return
        if self._finished:
            raise RuntimeError("Response writer is already finished")
        self._commands.put_nowait(_ResponseCommand("chunk", text, kwargs))

    def finish(self, **kwargs: Any) -> None:
        """Queue the response boundary without waiting for channel delivery."""
        if self._finished:
            return
        self._finished = True
        self._commands.put_nowait(_ResponseCommand("finish", None, kwargs))

    def interrupt(self) -> None:
        """Discard pending output and request interrupted delivery cleanup."""
        self._interrupted = True
        if self._end_started:
            return
        while not self._commands.empty():
            self._commands.get_nowait()
        self._finished = True
        self._commands.put_nowait(
            _ResponseCommand("finish", None, {"interrupted": True})
        )

    async def deliver(self) -> None:
        """Deliver queued commands."""
        try:
            if self._interrupted:
                return

            self._delivery_started = True
            await self._channel.send_response_chunk_start(
                self._recipient_id, **self._start_kwargs
            )
            if self._interrupted:
                await self._cleanup_interrupted_delivery()
                return
            await self._deliver_commands()
        except asyncio.CancelledError:
            await self._cleanup_interrupted_delivery()
            raise
        except Exception as error:
            structlogger.exception(
                "output_channel.response_delivery_failed",
                channel=type(self._channel).__name__,
                error_type=type(error).__name__,
            )
            await self._cleanup_interrupted_delivery()

    async def _deliver_commands(self) -> None:
        while True:
            command = await self._commands.get()
            if command.operation == "finish":
                self._end_started = True
                end_kwargs = dict(command.kwargs)
                end_kwargs["interrupted"] = self._interrupted or bool(
                    command.kwargs.get("interrupted")
                )
                await self._channel.send_response_chunk_end(
                    self._recipient_id,
                    **end_kwargs,
                )
                return
            await self._channel.send_response_chunk(
                self._recipient_id, command.text or "", **command.kwargs
            )

    async def _cleanup_interrupted_delivery(self) -> None:
        if not self._delivery_started or self._end_started:
            return
        self._end_started = True
        with contextlib.suppress(Exception):
            await self._channel.send_response_chunk_end(
                self._recipient_id, interrupted=True
            )


@dataclass
class OutputDeliveryResult:
    """Result returned by output channels after delivering a bot response."""

    events: List[Event] = field(default_factory=list)
    failed: bool = False

    def __bool__(self) -> bool:
        """Return whether the result contains any delivery signal."""
        return self.failed or bool(self.events)

    def extend(self, other: Optional[OutputDeliveryResult]) -> None:
        """Merge another delivery result into this result."""
        if not other:
            return

        self.events.extend(other.events)
        self.failed = self.failed or other.failed


class UserMessage:
    """Represents an incoming message.

    Includes the channel the responses should be sent to.
    """

    def __init__(
        self,
        text: Optional[Text] = None,
        output_channel: Optional["OutputChannel"] = None,
        sender_id: Optional[Text] = None,
        parse_data: Optional[Dict[Text, Any]] = None,
        input_channel: Optional[Text] = None,
        message_id: Optional[Text] = None,
        metadata: Optional[Dict] = None,
        is_voice: bool = False,
        dtmf_field_name: Optional[Text] = None,
        **kwargs: Any,
    ) -> None:
        """Creates a ``UserMessage`` object.

        Args:
            text: the message text content.
            output_channel: the output channel which should be used to send
                bot responses back to the user.
            sender_id: the message owner ID.
            parse_data: rasa data about the message.
            input_channel: the name of the channel which received this message.
            message_id: ID of the message.
            metadata: additional metadata for this message.
            is_voice: whether the message arrived over a voice channel.
            dtmf_field_name: field for which the keypad input was collected.
            **kwargs: additional arguments which will be included in the message.
        """
        self.text = text.strip() if text else text

        if message_id is not None:
            self.message_id = str(message_id)
        else:
            self.message_id = uuid.uuid4().hex

        if output_channel is not None:
            self.output_channel = output_channel
        else:
            self.output_channel = CollectingOutputChannel()

        if sender_id is not None:
            self.sender_id = str(sender_id)
        else:
            self.sender_id = DEFAULT_SENDER_ID

        self.input_channel = input_channel
        self.is_voice = is_voice
        self.dtmf_field_name = dtmf_field_name

        self.parse_data = parse_data
        self.metadata = metadata
        self.headers = kwargs.get("headers", None)


OnNewMessageType = Callable[[UserMessage], Awaitable[Any]]


class RuntimeAgent:
    """Accesses the runtime agent through the Sanic app context."""

    def __init__(self, app: Sanic) -> None:
        self._app = app

    @property
    def agent(self) -> "Agent":
        """Return the currently loaded agent."""
        agent = getattr(self._app.ctx, "agent", None)
        if agent is None:
            raise RasaException("Agent is not initialized.")
        return agent

    @property
    def model_metadata(self) -> Optional["ModelMetadata"]:
        """Return model metadata from the currently loaded agent."""
        return self.agent.model_metadata

    @property
    def recording_config(self) -> Optional["RecordingConfig"]:
        """Return call recording configuration.

        Mantle loads this from ``integrations.yml``. CALM loads it from
        ``endpoints.yml``.
        """
        return self.agent.endpoints.recordings if self.agent.endpoints else None

    @property
    def event_broker(self) -> Optional["EventBroker"]:
        """Return the event broker configured on the tracker store."""
        return self.agent.tracker_store.event_broker

    @property
    def voice_silence_timeout(self) -> Optional[float]:
        """Return the agent-wide voice silence timeout, in seconds.

        CALM has no agent-wide timeout, so this is ``None`` and the voice
        channel supplies the value. Mantle reads ``voice.silence_timeout``
        from ``agent.yml``.
        """
        processor = self.agent.processor
        if processor is None:
            return None
        return processor.voice_silence_timeout()

    async def handle_conversation(
        self,
        input_queue: Any,
        output_channel: "OutputChannel",
        channel_controller: "Optional[ChannelController]" = None,
    ) -> None:
        """Delegate queued conversation handling to the currently loaded agent."""
        await self.agent.handle_conversation(
            input_queue, output_channel, channel_controller
        )

    async def handle_message(self, message: UserMessage) -> None:
        """Delegate message handling to the currently loaded agent."""
        await self.agent.handle_message(message)

    def cancel_in_flight_turn(self, sender_id: str) -> None:
        """Cancel the in-flight turn for *sender_id* (e.g. on a voice barge-in).

        Lock-free and best-effort: signals the conversation's cancellation
        token so the engine stops generating and emitting further responses.
        A no-op when no processor or no active turn exists.
        """
        processor = self.agent.processor
        if processor is not None:
            processor.cancel_background_tasks(sender_id)


def register(
    input_channels: List[InputChannel], app: Sanic, route: Optional[Text]
) -> None:
    """Registers input channel blueprints with Sanic."""

    async def handler(message: UserMessage) -> None:
        await app.ctx.agent.handle_message(message)

    for channel in input_channels:
        if route:
            p = urljoin(route, channel.url_prefix())
        else:
            # Sanic 25 skips url_prefix=None when registering, so Blueprint's
            # own prefix applies. Channel code often passes Blueprint(name,
            # __name__), which sets that prefix to the module path. "" forces
            # an empty override (Sanic 22 behaviour when route is unset).
            p = ""

        blueprint = channel.conversation_blueprint(RuntimeAgent(app)) or (
            channel.blueprint(handler)
        )
        if blueprint is None:
            raise NotImplementedError(
                f"{channel.__class__.__name__} needs to provide blueprint() "
                f"or conversation_blueprint()."
            )

        app.blueprint(blueprint, url_prefix=p)

    app.ctx.input_channels = input_channels


class InputChannel:
    """Input channel base class."""

    @classmethod
    def name(cls) -> Text:
        """Every input channel needs a name to identify it."""
        return cls.__name__

    @classmethod
    def from_credentials(cls, credentials: Optional[Dict[Text, Any]]) -> InputChannel:
        return cls()

    def url_prefix(self) -> Text:
        return self.name()

    def blueprint(self, on_new_message: OnNewMessageType) -> Optional[Blueprint]:
        """Defines a Sanic blueprint for callback-based message handling.

        The blueprint will be attached to a running sanic server and handle
        incoming routes it registered for.
        """
        return None

    def conversation_blueprint(self, agent: "RuntimeAgent") -> Optional[Blueprint]:
        """Defines a Sanic blueprint that receives the runtime agent directly.

        Conversation-based channels can override this instead of ``blueprint()`` when
        they need to spawn async tasks that process events from an input queue.
        """
        return None

    @classmethod
    def raise_missing_credentials_exception(cls) -> NoReturn:
        raise RasaException(
            f"To use the {cls.name()} input channel, you need to "
            f"pass a credentials file using '--credentials'. "
            f"The argument should be a file path pointing to "
            f"a yml file containing the {cls.name()} authentication "
            f"information. Details in the docs: "
            f"{DOCS_URL_CONNECTORS}"
        )

    def get_output_channel(self) -> Optional["OutputChannel"]:
        """Create ``OutputChannel`` based on information provided by the input channel.

        Implementing this function is not required. If this function returns a valid
        ``OutputChannel`` this can be used by Rasa to send bot responses to the user
        without the user initiating an interaction.

        Returns:
            ``OutputChannel`` instance or ``None`` in case creating an output channel
             only based on the information present in the ``InputChannel`` is not
             possible.
        """
        pass

    def get_output_channel_for_conversation(
        self, conversation_id: Text
    ) -> Optional["OutputChannel"]:
        """Create an output channel for async updates to a conversation.

        Channels can override this when they need to check local live-session
        ownership before delivering a proactive async task update.
        """
        return self.get_output_channel()

    async def on_async_task_update(
        self,
        conversation_id: Text,
        task_id: Text,
        processor: "MessageProcessor",
    ) -> bool:
        """Handle an async task update for a conversation owned by this channel.

        Channels with local live delivery state can override this hook, create the
        appropriate ``OutputChannel``, and ask the message processor to flush the
        pending async update from tracker state.

        Returns:
            ``True`` if the channel delivered a pending async update.
        """
        output_channel = self.get_output_channel_for_conversation(conversation_id)
        if output_channel is None:
            return False

        return await processor.deliver_pending_async_update(
            conversation_id=conversation_id,
            output_channel=output_channel,
            input_channel=self.name(),
        )

    def get_metadata(self, request: Request) -> Optional[Dict[Text, Any]]:
        """Extracts additional information from the incoming request.

         Implementing this function is not required. However, it can be used to extract
         metadata from the request. The return value is passed on to the
         ``UserMessage`` object and stored in the conversation tracker.

        Args:
            request: incoming request with the message of the user

        Returns:
            Metadata which was extracted from the request.
        """
        pass


def decode_jwt(bearer_token: Text, jwt_key: Text, jwt_algorithm: Text) -> Dict:
    """Decodes a Bearer Token using the specific JWT key and algorithm.

    Args:
        bearer_token: Encoded Bearer token
        jwt_key: Public JWT key for decoding the Bearer token
        jwt_algorithm: JWT algorithm used for decoding the Bearer token

    Returns:
        `Dict` containing the decoded payload if successful or an exception
        if unsuccessful
    """
    authorization_header_value = bearer_token.replace(BEARER_TOKEN_PREFIX, "")
    return jwt.decode(authorization_header_value, jwt_key, algorithms=jwt_algorithm)


def decode_bearer_token(
    bearer_token: Text, jwt_key: Text, jwt_algorithm: Text
) -> Optional[Dict]:
    """Decodes a Bearer Token using the specific JWT key and algorithm.

    Args:
        bearer_token: Encoded Bearer token
        jwt_key: Public JWT key for decoding the Bearer token
        jwt_algorithm: JWT algorithm used for decoding the Bearer token

    Returns:
        `Dict` containing the decoded payload if successful or `None` if unsuccessful
    """
    # noinspection PyBroadException
    try:
        return decode_jwt(bearer_token, jwt_key, jwt_algorithm)
    except jwt.exceptions.InvalidSignatureError:
        logger.error("JWT public key invalid.")
    except Exception:
        logger.exception("Failed to decode bearer token.")

    return None


def caller_requested_streaming(output_channel: "OutputChannel") -> bool:
    """Whether this turn should deliver tokens as they arrive.

    ``supports_streaming`` means the channel can accept chunks. A channel such
    as A2A stores the caller's choice on ``streaming_chosen`` and still accepts
    chunks when that choice is false, so a streaming custom action stays on
    ``run_streaming`` and the channel assembles one message.
    """
    chosen = getattr(output_channel, "streaming_chosen", None)
    if isinstance(chosen, bool):
        return chosen
    return bool(output_channel.supports_streaming)


class OutputChannel:
    """Output channel base class.

    Provides sane implementation of the send methods
    for text only output channels.
    """

    def __init__(self) -> None:
        self.tracker_state: Optional[Dict[str, Any]] = None
        self._tracker: Optional[DialogueStateTracker] = None
        self._accumulated_streaming_text: str = ""
        self._response_queue: asyncio.Queue[ResponseWriter] = asyncio.Queue()
        self._response_worker_task: Optional[asyncio.Task[None]] = None
        self._active_response_writer: Optional[ResponseWriter] = None

    @classmethod
    def name(cls) -> Text:
        """Every output channel needs a name to identify it."""
        return cls.__name__

    def attach_tracker_state(self, tracker: DialogueStateTracker) -> None:
        """Attaches the tracker reference; computes state only if needed."""
        self._tracker = tracker
        if self.wants_tracker_state:
            self.tracker_state = tracker.current_state(EventVerbosity.AFTER_RESTART)

    @property
    def wants_tracker_state(self) -> bool:
        """Whether this channel needs the expensive serialized tracker state.

        Defaults to `True` to preserve existing behaviour for any channel we
        haven't specifically confirmed doesn't need it - including
        `CollectingOutputChannel` itself, which is a documented public API
        for custom connectors to construct directly and read `tracker_state`
        from (see the custom-connectors docs). Only channels we've audited
        and control end-to-end (e.g. Rasa's own internal REST/A2A output
        channel implementations) override this to `False`.
        """
        return True

    @property
    def supports_streaming(self) -> bool:
        """Whether this channel can accept streamed chunks.

        This is a capability, not the caller's choice. Custom actions use it
        to stay on ``run_streaming``. Whether those chunks should be delivered
        live is :func:`caller_requested_streaming`.
        """
        return False

    def send_text_message_awaits_playback(self) -> bool:
        """Whether ``send_text_message`` waits until playback has been sent.

        The default is false, so a write that exceeds a short timeout is
        cancelled. A custom voice channel should inherit ``VoiceOutputChannel``,
        which returns true. Playback then gets a longer bound and is left
        running if that bound is hit, instead of being cut off.
        """
        return False

    @property
    def supports_response_writer(self) -> bool:
        """Whether LLM streaming should enqueue delivery for this channel."""
        return False

    def open_response(self, recipient_id: Text, **kwargs: Any) -> ResponseWriter:
        """Open a serialized response whose delivery runs in the background."""
        writer = ResponseWriter(
            self,
            recipient_id,
            start_kwargs=kwargs,
        )
        self._response_queue.put_nowait(writer)
        self._ensure_response_worker()
        return writer

    def _ensure_response_worker(self) -> None:
        if self._response_worker_task is None or self._response_worker_task.done():
            self._response_worker_task = asyncio.create_task(
                self._deliver_queued_responses()
            )

    async def _deliver_queued_responses(self) -> None:
        while not self._response_queue.empty():
            writer = self._response_queue.get_nowait()
            self._active_response_writer = writer
            try:
                await writer.deliver()
            finally:
                self._active_response_writer = None
                self._response_queue.task_done()

    def interrupt_response_deliveries(self) -> None:
        """Interrupt active and queued response writers without waiting for them."""
        if self._active_response_writer is not None:
            self._active_response_writer.interrupt()
        while not self._response_queue.empty():
            writer = self._response_queue.get_nowait()
            writer.interrupt()
            self._response_queue.task_done()

    async def wait_for_response_deliveries(self) -> None:
        """Wait until all currently queued response deliveries have settled."""
        await self._response_queue.join()

    async def shutdown_response_deliveries(self) -> None:
        """Cancel the response worker and wait for channel cleanup."""
        self.interrupt_response_deliveries()
        if self._response_worker_task is None:
            return
        self._response_worker_task.cancel()
        await asyncio.gather(self._response_worker_task, return_exceptions=True)
        self._response_worker_task = None

    async def send_response_chunk_start(
        self,
        recipient_id: Text,
        **kwargs: Any,
    ) -> None:
        """Indicates the start of a streaming response.

        Used for streaming generative AI responses. Default implementation does nothing.

        Args:
            recipient_id: The recipient ID.
            **kwargs: Additional arguments.
        """
        self._accumulated_streaming_text = ""

    async def send_response_chunk(
        self,
        recipient_id: Text,
        chunk: Text,
        **kwargs: Any,
    ) -> None:
        """Send a chunk of response to the client.

        Used for streaming generative AI responses. Default implementation does nothing.

        Args:
            recipient_id: The recipient ID.
            chunk: The response chunk to send. Full response is built by concatenating
                all chunks sent.
            **kwargs: Additional arguments.

        Returns:
            None
        """
        self._accumulated_streaming_text += chunk
        self._notify_streaming_response()

    def _notify_streaming_response(self) -> None:
        """Notify plugins about the streaming response progress."""
        if getattr(self, "_tracker", None):
            from rasa.plugin import plugin_manager

            plugin_manager().hook.after_response_chunk(
                tracker=self._tracker,
                accumulated_text=self._accumulated_streaming_text,
            )

    async def send_response_chunk_end(
        self,
        recipient_id: Text,
        **kwargs: Any,
    ) -> None:
        """Indicates the end of a streaming response.

        Used for streaming generative AI responses. Default implementation does nothing.

        Args:
            recipient_id: The recipient ID.
            **kwargs: Additional arguments.
        """
        pass

    def note_last_streamed_bot_message_was_filler(self, was_filler: bool) -> None:
        """Record whether the last streamed bot audio was a filler-style message.

        Voice channels use this to choose pacing before the next bot utterance
        (e.g. a longer gap after filler, shorter between consecutive replies).
        Default implementation is a no-op.
        """
        pass

    def _is_duplicate_of_last_streamed_response(self, text: str) -> bool:
        """Return True if *text* matches the last streamed response.

        Compares the stripped incoming text against the accumulated streaming
        text from the most recent ``send_response_chunk`` sequence. Used by
        text channels that need to suppress a completed response after direct
        streaming delivery.
        """
        last = self._accumulated_streaming_text.strip()
        return bool(last) and text.strip() == last

    async def send_response(
        self,
        recipient_id: Text,
        message: Dict[Text, Any],
    ) -> Optional[OutputDeliveryResult]:
        """Send a message to the client."""
        if message.get("quick_replies"):
            await self.send_quick_replies(
                recipient_id,
                message.pop("text"),
                message.pop("quick_replies"),
                **message,
            )
        elif message.get("buttons"):
            await self.send_text_with_buttons(
                recipient_id, message.pop("text"), message.pop("buttons"), **message
            )
        elif message.get("text"):
            await self.send_text_message(recipient_id, message.pop("text"), **message)

        if message.get("custom"):
            await self.send_custom_json(recipient_id, message.pop("custom"), **message)

        # if there is an image we handle it separately as an attachment
        if message.get("image"):
            await self.send_image_url(recipient_id, message.pop("image"), **message)

        if message.get("attachment"):
            await self.send_attachment(
                recipient_id, message.pop("attachment"), **message
            )

        if message.get("elements"):
            await self.send_elements(recipient_id, message.pop("elements"), **message)

        return None

    def take_tts_delivery_result(
        self, recipient_id: Text
    ) -> Optional[OutputDeliveryResult]:
        """Return a delivery signal for the message just delivered, if any.

        Voice channels override this to return TTS timing.
        """
        return None

    async def send_text_message(
        self,
        recipient_id: Text,
        text: Text,
        **kwargs: Any,
    ) -> None:
        """Send a message through this channel."""
        raise NotImplementedError(
            "Output channel needs to implement a send message for simple texts."
        )

    async def send_image_url(
        self, recipient_id: Text, image: Text, **kwargs: Any
    ) -> None:
        """Sends an image. Default will just post the url as a string."""
        await self.send_text_message(recipient_id, f"Image: {image}")

    async def send_attachment(
        self, recipient_id: Text, attachment: Text, **kwargs: Any
    ) -> None:
        """Sends an attachment. Default will just post as a string."""
        await self.send_text_message(recipient_id, f"Attachment: {attachment}")

    async def send_text_with_buttons(
        self,
        recipient_id: Text,
        text: Text,
        buttons: List[Dict[Text, Any]],
        **kwargs: Any,
    ) -> None:
        """Sends buttons to the output.

        Default implementation will just post the buttons as a string.
        """
        await self.send_text_message(recipient_id, text)
        for idx, button in enumerate(buttons):
            button_msg = cli_utils.button_to_string(button, idx)
            await self.send_text_message(recipient_id, button_msg)

    async def send_buttons(
        self,
        recipient_id: Text,
        buttons: List[Dict[Text, Any]],
        **kwargs: Any,
    ) -> None:
        """Send buttons without accompanying text.

        Use after a streamed utterance so chat clients receive actions without
        repeating the streamed text. Default falls back to
        :meth:`send_text_with_buttons` with an empty text string for channels
        that do not override this method.
        """
        if not buttons:
            return
        await self.send_text_with_buttons(recipient_id, "", buttons, **kwargs)

    async def send_text_with_buttons_concise(
        self,
        recipient_id: Text,
        text: Optional[Text],
        buttons: List[Dict[Text, Any]],
        **kwargs: Any,
    ) -> None:
        """Sends buttons in a concise format, useful for voice channels.

        Empty, missing, or whitespace-only *text* (for example after streamed
        TTS via :meth:`send_buttons`) still speaks button titles so voice
        channels degrade gracefully instead of raising ``IndexError``.
        """
        spoken_text = (text or "").strip()
        if spoken_text and spoken_text[-1] not in {".", "!", "?", ":"}:
            spoken_text += "."
        if spoken_text:
            spoken_text += " "
        for idx, button in enumerate(buttons):
            spoken_text += button["title"]
            if idx != len(buttons) - 1:
                spoken_text += ", "
        await self.send_text_message(recipient_id, spoken_text)

    async def send_quick_replies(
        self,
        recipient_id: Text,
        text: Text,
        quick_replies: List[Dict[Text, Any]],
        **kwargs: Any,
    ) -> None:
        """Sends quick replies to the output.

        Default implementation will just send as buttons.
        """
        await self.send_text_with_buttons(recipient_id, text, quick_replies)

    async def send_elements(
        self, recipient_id: Text, elements: Iterable[Dict[Text, Any]], **kwargs: Any
    ) -> None:
        """Sends elements to the output.

        Default implementation will just post the elements as a string.
        """
        for element in elements:
            element_msg = "{title} : {subtitle}".format(
                title=element.get("title", ""), subtitle=element.get("subtitle", "")
            )
            await self.send_text_with_buttons(
                recipient_id, element_msg, element.get("buttons", [])
            )

    async def send_custom_json(
        self, recipient_id: Text, json_message: Dict[Text, Any], **kwargs: Any
    ) -> None:
        """Sends json dict to the output channel.

        Default implementation will just post the json contents as a string.
        """
        await self.send_text_message(recipient_id, json.dumps(json_message))

    async def hangup(self, recipient_id: Text, **kwargs: Any) -> None:
        """Indicate that the conversation should be ended."""
        pass

    async def notify_message_processing_started(self) -> None:
        """Notify that message processing started."""
        pass

    async def notify_message_processing_completed(self) -> None:
        """Notify that message is processed."""
        pass

    async def record_turn_outcome(self, outcome: Any) -> None:
        """Record the engine's turn result. The default does nothing.

        Mantle calls this with ``TurnResult`` so the A2A channel can map the
        task state after the turn. Other channels ignore it.
        """
        del outcome

    async def interrupt_response(self) -> None:
        """Interrupt any response currently being delivered by this channel."""
        pass

    async def resume_response(self) -> None:
        """Stop withholding responses because new user input is being processed.

        Only voice channels withhold output, after a barge-in; see
        :attr:`is_response_interrupted`.
        """
        pass

    @property
    def is_response_interrupted(self) -> bool:
        """Whether new responses are withheld until fresh user input arrives.

        Only voice channels withhold output after a barge-in.
        """
        return False


async def complete_channel_turn(
    output_channel: OutputChannel, tracker: DialogueStateTracker
) -> None:
    """Attach ``tracker`` and notify that message processing completed.

    Callers that already have a tracker use this so a channel that maps the
    turn (A2A) publishes from that tracker.
    """
    output_channel.attach_tracker_state(tracker)
    await output_channel.notify_message_processing_completed()


class CollectingOutputChannel(OutputChannel):
    """Output channel that collects send messages in a list.

    (doesn't send them anywhere, just collects them).
    """

    def __init__(self) -> None:
        """Initialise list to collect messages."""
        super().__init__()
        self.messages: List[Dict[Text, Any]] = []

    @classmethod
    def name(cls) -> Text:
        """Name of the channel."""
        return "collector"

    @staticmethod
    def _message(
        recipient_id: Text,
        text: Optional[Text] = None,
        image: Optional[Text] = None,
        buttons: Optional[List[Dict[Text, Any]]] = None,
        attachment: Optional[Text] = None,
        custom: Optional[Dict[Text, Any]] = None,
    ) -> Dict:
        """Create a message object that will be stored."""
        obj = {
            "recipient_id": recipient_id,
            "text": text,
            "image": image,
            "buttons": buttons,
            "attachment": attachment,
            "custom": custom,
        }

        # filter out any values that are `None`
        return {k: v for k, v in obj.items() if v is not None}

    def latest_output(self) -> Optional[Dict[Text, Any]]:
        if self.messages:
            return self.messages[-1]
        else:
            return None

    async def _persist_message(self, message: Dict[Text, Any]) -> None:
        self.messages.append(message)

    async def send_text_message(
        self,
        recipient_id: Text,
        text: Text,
        **kwargs: Any,
    ) -> None:
        for message_part in text.strip().split("\n\n"):
            await self._persist_message(self._message(recipient_id, text=message_part))

    async def send_image_url(
        self, recipient_id: Text, image: Text, **kwargs: Any
    ) -> None:
        """Sends an image. Default will just post the url as a string."""
        await self._persist_message(self._message(recipient_id, image=image))

    async def send_attachment(
        self, recipient_id: Text, attachment: Text, **kwargs: Any
    ) -> None:
        """Sends an attachment. Default will just post as a string."""
        await self._persist_message(self._message(recipient_id, attachment=attachment))

    async def send_text_with_buttons(
        self,
        recipient_id: Text,
        text: Text,
        buttons: List[Dict[Text, Any]],
        **kwargs: Any,
    ) -> None:
        await self._persist_message(
            self._message(recipient_id, text=text, buttons=buttons)
        )

    async def send_buttons(
        self,
        recipient_id: Text,
        buttons: List[Dict[Text, Any]],
        **kwargs: Any,
    ) -> None:
        """Persist buttons without a text field (omits empty bubbles)."""
        if not buttons:
            return
        await self._persist_message(self._message(recipient_id, buttons=buttons))

    async def send_custom_json(
        self, recipient_id: Text, json_message: Dict[Text, Any], **kwargs: Any
    ) -> None:
        await self._persist_message(self._message(recipient_id, custom=json_message))


BASIC_AUTH_SCHEME = "Basic"


def create_auth_requested_response_provider(
    realm: str,
) -> Callable[[Request, Any, Any], ResponseWithAuthRequested]:
    def _provider(
        request: Request, *args: Any, **kwargs: Any
    ) -> ResponseWithAuthRequested:
        return ResponseWithAuthRequested(scheme=BASIC_AUTH_SCHEME, realm=realm)

    return _provider


class ResponseWithAuthRequested(Unauthorized):
    """Custom exception to request authentication."""

    def __init__(self, scheme: str, realm: str) -> None:
        super().__init__(
            message="Authentication requested.", scheme=scheme, realm=realm
        )


def requires_basic_auth(
    username: Optional[Text],
    password: Optional[Text],
    auth_request_provider: Optional[Callable[[Request, Any, Any], Unauthorized]] = None,
) -> Callable:
    """Decorator to require basic auth for a route.

    Args:
        username: The username to check against.
        password: The password to check against.
        auth_request_provider: Optional function to provide a custom
            response when authentication is requested. This function should
            return an instance of `Unauthorized` with the necessary
            authentication headers.

    Returns:
        A decorator that checks for basic authentication.

    Raises:
        Unauthorized: If the authentication fails or if authentication is
            requested without necessary credentials (headers).
    """

    def decorator(func: Callable) -> Callable:
        @wraps(func)
        async def wrapper(request: Request, *args: Any, **kwargs: Any) -> Any:
            if not username or not password:
                return await func(request, *args, **kwargs)

            auth_header = request.headers.get("Authorization")

            # Some systems will first send a request without an authorization header
            # to check if the endpoint is available. In this case, we need to
            # return am Unauthorized response with the necessary authorization header
            # to indicate that the endpoint requires authorization.
            if not auth_header and auth_request_provider:
                # if the request does not contain an authorization header,
                # we raise an exception to request authorization

                exception = auth_request_provider(request, *args, **kwargs)
                logger.debug(
                    f"Responding with {exception.status_code} and "
                    f"necessary auth headers {exception.headers}"
                )
                raise exception

            if not auth_header or not auth_header.startswith("Basic "):
                logger.error("Missing or invalid authorization header.")
                raise Unauthorized("Missing or invalid authorization header.")

            encoded = b64encode(f"{username}:{password}".encode()).decode()
            username_password_digest: str = auth_header[len(BASIC_AUTH_SCHEME) :]
            username_password_digest = username_password_digest.strip()

            if not hmac.compare_digest(username_password_digest, encoded):
                logger.error("Invalid username or password.")
                raise Unauthorized("Invalid username or password.")

            return await func(request, *args, **kwargs)

        return wrapper

    return decorator
